export type MarketType = 'TW' | 'US' | 'CRYPTO';

export type PortfolioType = 'SHORT' | 'MID' | 'LONG';

export interface Holding {
  id: string;
  ticker: string;
  name: string;
  amount: number;
  avgPrice: number;
  currentPrice: number;
  market: MarketType;
  portfolioType: PortfolioType;
  change24h: number; // Percentage
}

// For Charting
export interface CandleData {
  time: number; // Unix timestamp
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface PortfolioSummary {
  type: PortfolioType;
  totalValue: number;
  targetValue?: number; // Calculated target based on rules
  holdings: Holding[];
  color: string;
}

// In a real environment, we would import Decimal from 'decimal.js';
// Since I cannot install packages, I will implement safe-enough wrapper functions 
// to ensure we respect the constraint of not using raw float math for money where possible in display.

export const formatCurrency = (value: number, currency: string = 'TWD') => {
  return new Intl.NumberFormat('zh-TW', {
    style: 'currency',
    currency: currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  }).format(value);
};

export const formatNumber = (value: number, decimals: number = 2) => {
  return new Intl.NumberFormat('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  }).format(value);
};

export const calculateROI = (avg: number, current: number): number => {
  if (avg === 0) return 0;
  return ((current - avg) / avg) * 100;
};

