// Mock 5-min Candle Data Generator (Simulating yfinance)
export const generateMockCandles = (basePrice: number, count: number = 200): CandleData[] => {
  let time = Math.floor(Date.now() / 1000) - (count * 5 * 60);
  let currentPrice = basePrice;
  const data: CandleData[] = [];

  for (let i = 0; i < count; i++) {
    const volatility = basePrice * 0.005; // 0.5% volatility
    const change = (Math.random() - 0.5) * volatility;

    const open = currentPrice;
    const close = currentPrice + change;
    const high = Math.max(open, close) + Math.random() * volatility * 0.5;
    const low = Math.min(open, close) - Math.random() * volatility * 0.5;

    data.push({
      time: time,
      open: parseFloat(open.toFixed(2)),
      high: parseFloat(high.toFixed(2)),
      low: parseFloat(low.toFixed(2)),
      close: parseFloat(close.toFixed(2)),
    });

    currentPrice = close;
    time += 5 * 60; // Add 5 minutes
  }

  return data;
};

import React, { useEffect, useRef, useState } from 'react';
import { createChart, ColorType, IChartApi, ISeriesApi } from 'lightweight-charts';
import { CandleData } from '../types';

interface Props {
  data: CandleData[];
  ticker: string;
}

const CandlestickChart: React.FC<Props> = ({ data, ticker }) => {
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRef = useRef<ISeriesApi<"Candlestick"> | null>(null);

  useEffect(() => {
    if (!chartContainerRef.current) return;

    const chart = createChart(chartContainerRef.current, {
      layout: {
        background: { type: ColorType.Solid, color: '#151a21' }, // Matching card bg
        textColor: '#94a3b8',
      },
      grid: {
        vertLines: { color: '#2d3748' },
        horzLines: { color: '#2d3748' },
      },
      width: chartContainerRef.current.clientWidth,
      height: 400,
      timeScale: {
        timeVisible: true,
        secondsVisible: false,
      },
    });

    const candlestickSeries = chart.addCandlestickSeries({
      upColor: '#10b981', // Green
      downColor: '#ef4444', // Red
      borderVisible: false,
      wickUpColor: '#10b981',
      wickDownColor: '#ef4444',
    });

    candlestickSeries.setData(data);

    chartRef.current = chart;
    seriesRef.current = candlestickSeries;

    const handleResize = () => {
      if (chartContainerRef.current) {
        chart.applyOptions({ width: chartContainerRef.current.clientWidth });
      }
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      chart.remove();
    };
  }, []);

  useEffect(() => {
    if (seriesRef.current && data.length > 0) {
      seriesRef.current.setData(data);
      chartRef.current?.timeScale().fitContent();
    }
  }, [data]);

  return (
    <div className="w-full bg-dark-card rounded-xl p-4 shadow-lg border border-dark-border">
      <div className="flex justify-between items-center mb-4">
        <div>
           <h3 className="text-xl font-bold text-white flex items-center gap-2">
            <span className="text-brand-secondary">{ticker}</span>
            <span className="text-sm font-normal text-slate-400">5-Minute Intervals (Yearly data)</span>
          </h3>
          <p className="text-xs text-slate-500 mt-1">Data Source: Yahoo Finance (Simulated via PostgreSQL)</p>
        </div>
      </div>
      <div ref={chartContainerRef} className="w-full h-[400px]" />
    </div>
  );
};

export default CandlestickChart;

import React from 'react';
