  const [chartData, setChartData] = useState<CandleData[]>([]);

  const chartSectionRef = useRef<HTMLDivElement>(null);

  // Initial Data Load (Simulating DB fetch)
  useEffect(() => {
    // Filter holdings based on market
    const marketHoldings = MOCK_HOLDINGS.filter(h => h.market === currentMarket);
    setHoldings(marketHoldings);
    setSelectedHolding(null);
  }, [currentMarket]);

  // Handle Holding Selection (Simulating yfinance fetch)
  const handleSelectHolding = (holding: Holding) => {
    setSelectedHolding(holding);
    // Simulate fetching 1 year of 5-min data
    // In real app: await fetch(`/api/candles?ticker=${holding.ticker}&interval=5m&range=1y`)
    const mockData = generateMockCandles(holding.currentPrice, 500); // 500 candles for demo
    setChartData(mockData);

    // Smooth scroll to chart
    setTimeout(() => {
        chartSectionRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  // --- Calculations based on Logic Requirements ---
  const currencySymbol = currentMarket === 'US' || currentMarket === 'CRYPTO' ? 'USD' : 'TWD';

  // 1. Calculate Total Asset Value
  const totalAssets = useMemo(() => {
    return holdings.reduce((sum, h) => sum + (h.amount * h.currentPrice), 0);
  }, [holdings]);

  // 2. Define Targets
  // Rule: Short = 500k (fixed)
  // Rule: Long = 30% of Total
  // Rule: Mid = Remainder

  // Note: These rules are "Allocation Goals". The actual value might differ.
  // If we are in US/Crypto, 500k TWD needs conversion? 
  // For simplicity in this dashboard, I'll assume the rules apply to the *currency of the view* or 500k is just a generic unit.
  // Let's assume 500,000 is the raw number for the Short bucket target regardless of currency for this demo, 
  // OR strictly 500k TWD. If US/Crypto, let's just stick to the numeric 500,000 for simplicity as requested "50萬".

  const TARGET_SHORT = 500000;
  const targetLong = totalAssets * 0.30;
  // Mid is remaining. If Total < Short + Long, Mid might be 0 conceptually or negative.
