export default App;

export type MarketType = 'TW' | 'US' | 'CRYPTO';

export type PortfolioType = 'SHORT' | 'MID' | 'LONG' | 'FAMILY';

export interface Holding {
  id: string;
  ticker: string;
  name: string;
  amount: number;
  avgPrice: number;
  currentPrice: number;
  market: MarketType;
  portfolioType: PortfolioType;
  change24h: number; // Percentage
}

// For Charting
export interface CandleData {
  time: number; // Unix timestamp
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface PortfolioSummary {
  type: PortfolioType;
  totalValue: number;
  targetValue?: number; // Calculated target based on rules
  holdings: Holding[];
  color: string;
}

// In a real environment, we would import Decimal from 'decimal.js';

export const formatCurrency = (value: number, currency: string = 'TWD') => {
  return new Intl.NumberFormat('zh-TW', {
    style: 'currency',
    currency: currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 0, // Taiwan stock usually doesn't need decimals for totals
  }).format(value);
};

export const formatNumber = (value: number, decimals: number = 2) => {
  return new Intl.NumberFormat('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  }).format(value);
};

export const calculateROI = (avg: number, current: number): number => {
  if (avg === 0) return 0;
  return ((current - avg) / avg) * 100;
};

// Parser for the specific CSV format provided by user
// Format: Ticker, Name, Amount, AvgPrice (Values might have commas and quotes e.g. "1,200")
export const parseStockCSV = (input: string) => {
  const lines = input.trim().split('\n');
  const results = [];

  for (const line of lines) {
    if (!line.trim()) continue;

    // Regex to split by comma but ignore commas inside quotes
    const regex = /(".*?"|[^",\s]+)(?=\s*,|\s*$)/g;
    const matches = line.match(regex);

    if (matches && matches.length >= 4) {
      const cleanNumber = (str: string) => {
        return parseFloat(str.replace(/["',]/g, ''));
      };

      const ticker = matches[0].replace(/['"]/g, '').trim();
      const name = matches[1].replace(/['"]/g, '').trim();
      const amount = cleanNumber(matches[2]);
      const avgPrice = cleanNumber(matches[3]);

      if (!isNaN(amount) && !isNaN(avgPrice)) {
        results.push({
          ticker,
          name,
          amount,
          avgPrice
        });
      }
    }
  }
  return results;
};

import React, { useState } from 'react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';
import { Holding, PortfolioType } from '../types';
import { formatCurrency, formatNumber, calculateROI, parseStockCSV } from '../utils/math';
import { TrendingUp, TrendingDown, Edit3, Save, X } from 'lucide-react';

interface Props {
  title: string;
  type: PortfolioType;
  holdings: Holding[];
  totalValue: number;
  targetValue: number;
  currency: string;
  onSelectHolding: (holding: Holding) => void;
  onUpdateHoldings?: (type: PortfolioType, newHoldings: any[]) => void;
  color: string;
  isOverflow?: boolean; // Marks if this is the Family column receiving overflow
  overflowSources?: { short: number; mid: number }; // Specific details for Family column
}

const PortfolioColumn: React.FC<Props> = ({ 
  title, 
  type,
  holdings, 
  totalValue, 
  targetValue,
  currency, 
  onSelectHolding,
  onUpdateHoldings,
  color,
  isOverflow,
  overflowSources
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [inputText, setInputText] = useState('');

  // Prepare data for Pie Chart
  const data = holdings.map(h => ({
    name: h.name || h.ticker,
    value: h.amount * h.currentPrice
  }));

  const chartData = data.length > 0 ? data : [{ name: '無持倉', value: 1 }];
  const COLORS = [color, '#64748b', '#475569', '#334155', '#94a3b8'];

  const handleSave = () => {
    if (onUpdateHoldings) {
        const parsed = parseStockCSV(inputText);
        onUpdateHoldings(type, parsed);
    }
    setIsEditing(false);
  };

  const handleEditClick = () => {
    // Generate current CSV representation for editing
    const csv = holdings.map(h => 
      `${h.ticker},${h.name},${h.amount},"${formatNumber(h.avgPrice, 2)}"`
    ).join('\n');
    setInputText(csv);
    setIsEditing(true);
  };

  const getPercentage = () => {
    if (targetValue === 0) return 0;
    return Math.min(100, (totalValue / targetValue) * 100);
  };

  const percentFilled = getPercentage();

  return (
    <div className={`bg-dark-card rounded-xl border flex flex-col h-[650px] shadow-lg relative overflow-hidden group transition-colors ${isEditing ? 'border-brand-primary' : 'border-dark-border'}`}>
        {/* Top Color Bar */}
        <div className="absolute top-0 left-0 w-full h-1" style={{ backgroundColor: color }}></div>

        {/* Header */}
        <div className="p-5 pb-2">
            <div className="flex justify-between items-start mb-2">
                <h3 className="text-slate-400 text-sm font-medium uppercase tracking-wider flex items-center gap-2">
                    {title}
                    {isOverflow && <span className="text-[10px] bg-slate-700 text-white px-1.5 py-0.5 rounded">溢出資金池</span>}
                </h3>
                {!isOverflow && onUpdateHoldings && (
                    <button 
                        onClick={handleEditClick}
                        className="text-slate-500 hover:text-white transition-colors"
                        title="輸入持倉"
                    >
                        <Edit3 size={16} />
                    </button>
                )}
            </div>

            <div className="flex justify-between items-baseline">
                <div className="text-2xl font-bold text-white mt-1">
                    {formatCurrency(totalValue, currency)}
                </div>
                <div className="text-right">
                     <span className="text-xs text-slate-500 block">目標配置</span>
                     <div className="text-sm font-semibold text-slate-300">{formatCurrency(targetValue, currency)}</div>
                </div>
            </div>

            {/* Progress Bar (Only for non-family to show usage) */}
            {!isOverflow && (
                 <div className="w-full bg-slate-800 h-1.5 mt-3 rounded-full overflow-hidden">
                    <div 
                        className="h-full rounded-full transition-all duration-500"
                        style={{ width: `${percentFilled}%`, backgroundColor: percentFilled > 100 ? '#ef4444' : color }}
                    ></div>
                 </div>
            )}

            {/* Overflow details for Family */}
            {isOverflow && overflowSources && (
                <div className="mt-2 text-xs text-slate-400 space-y-1">
                    <div className="flex justify-between">
                        <span>來自短期溢出:</span>
                        <span className="text-slate-200">{formatCurrency(overflowSources.short, currency)}</span>
                    </div>
                    <div className="flex justify-between">
                        <span>來自中期溢出:</span>
                        <span className="text-slate-200">{formatCurrency(overflowSources.mid, currency)}</span>
                    </div>
                </div>
            )}
        </div>

        {/* Editing Mode */}
        {isEditing ? (
            <div className="absolute inset-0 z-20 bg-dark-card p-4 flex flex-col animate-in fade-in zoom-in-95 duration-200">
                <div className="flex justify-between items-center mb-2">
                    <h4 className="text-white font-medium">編輯持倉 (CSV)</h4>
                    <button onClick={() => setIsEditing(false)} className="text-slate-400 hover:text-white"><X size={20}/></button>
                </div>
                <div className="text-xs text-slate-500 mb-2 p-2 bg-slate-800 rounded">
                    格式: 代號,名稱,股數,均價<br/>
                    範例: 2330,台積電,4,570
                </div>
                <textarea 
                    className="flex-1 w-full bg-[#0b0e11] border border-slate-700 rounded-lg p-3 text-sm text-slate-300 font-mono focus:outline-none focus:border-brand-primary resize-none"
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    placeholder="在此貼上您的CSV資料..."
                />
                <button 
                    onClick={handleSave}
                    className="mt-3 w-full bg-brand-primary hover:bg-indigo-600 text-white py-2 rounded-lg flex items-center justify-center gap-2 font-medium transition-colors"
                >
                    <Save size={16} /> 儲存變更
                </button>
            </div>
        ) : (
            <>
                {/* Chart Section */}
                <div className="h-40 w-full relative mb-2 shrink-0">
                    <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                            <Pie
                                data={chartData}
                                cx="50%"
                                cy="50%"
                                innerRadius={50}
                                outerRadius={70}
                                paddingAngle={3}
                                dataKey="value"
                                stroke="none"
                            >
                                {chartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={data.length > 0 ? COLORS[index % COLORS.length] : '#1e293b'} />
                                ))}
                            </Pie>
                            <Tooltip 
                                contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', borderRadius: '8px', color: '#fff', fontSize: '12px' }}
                                itemStyle={{ color: '#fff' }}
                                formatter={(value: number) => formatCurrency(value, currency)}
                            />
                        </PieChart>
                    </ResponsiveContainer>
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                        <div className="text-center">
                            <span className="text-[10px] text-slate-500 block">持倉數</span>
                            <span className="text-lg font-bold text-white">{holdings.length}</span>
                        </div>
                    </div>
                </div>

                {/* List Section */}
                <div className="flex-1 overflow-y-auto pr-1 space-y-2 px-4 pb-4">
                    {holdings.length === 0 && !isOverflow && (
                        <div className="text-center text-slate-600 py-8 text-sm flex flex-col items-center gap-2">
                            <span>尚無持倉</span>
                            <button onClick={handleEditClick} className="text-brand-secondary text-xs hover:underline">
                                點此匯入資料
                            </button>
                        </div>
                    )}
                    {isOverflow && holdings.length === 0 && (
                        <div className="text-center text-slate-600 py-8 text-sm">
                            目前無溢出資金
                        </div>
                    )}

                    {holdings.map((holding) => {
                        const holdingValue = holding.amount * holding.currentPrice;
                        const roi = calculateROI(holding.avgPrice, holding.currentPrice);
                        const isProfit = roi >= 0;

                        return (
                            <div 
                                key={holding.id}
                                onClick={() => onSelectHolding(holding)}
                                className="p-3 rounded-lg bg-[#1e232e] hover:bg-[#252b36] cursor-pointer transition-colors border border-transparent hover:border-slate-700 group/item"
                            >
                                <div className="flex justify-between items-start mb-1">
                                    <div className="flex flex-col">
                                        <span className="font-bold text-white text-sm group-hover/item:text-brand-secondary transition-colors">{holding.name}</span>
                                        <span className="text-[10px] text-slate-500">{holding.ticker}</span>
                                    </div>
                                    <span className="text-white font-medium text-sm">{formatCurrency(holdingValue, currency)}</span>
                                </div>
                                <div className="flex justify-between items-center text-xs mt-1">
                                    <span className="text-slate-500">
                                        {holding.amount}股 @ {formatNumber(holding.avgPrice, 0)}
                                    </span>
                                    <div className={`flex items-center gap-1 ${isProfit ? 'text-brand-success' : 'text-brand-danger'}`}>
                                        {isProfit ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
                                        <span>{formatNumber(roi)}%</span>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </>
        )}
    </div>
  );
};

export default PortfolioColumn;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { MarketType, PortfolioType, Holding, CandleData } from './types';
import { generateMockCandles } from './services/mockData';
import PortfolioColumn from './components/PortfolioColumn';
import CandlestickChart from './components/CandlestickChart';
import { formatCurrency } from './utils/math';
import { Wallet, Globe, TrendingUp, LayoutDashboard, PlusCircle, Activity, Info } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid'; // Actually we don't have uuid, lets use random string

const generateId = () => Math.random().toString(36).substr(2, 9);

const App: React.FC = () => {
  const [currentMarket, setCurrentMarket] = useState<MarketType>('TW');

  // State for different buckets
  const [shortHoldings, setShortHoldings] = useState<Holding[]>([]);
  const [midHoldings, setMidHoldings] = useState<Holding[]>([]);
  const [longHoldings, setLongHoldings] = useState<Holding[]>([]);

  const [selectedHolding, setSelectedHolding] = useState<Holding | null>(null);
  const [chartData, setChartData] = useState<CandleData[]>([]);

  const chartSectionRef = useRef<HTMLDivElement>(null);

  // Targets (Hardcoded as per requirement)
  const TOTAL_PRINCIPAL = 1200000; // 120萬 (Excluding Family)
  const TARGET_SHORT = 500000;
  const TARGET_LONG = TOTAL_PRINCIPAL * 0.30; // 360,000
  const TARGET_MID = TOTAL_PRINCIPAL - TARGET_SHORT - TARGET_LONG; // 340,000
  const TARGET_FAMILY = 240000; // 24萬 (Separate)

  // Initial Data Example (for Long Term to show data immediately)
  useEffect(() => {
    // We can pre-populate one bucket to demo functionality if needed, 
    // but starting clean or with the user provided example in a specific bucket is better.
    // For now, let's leave them empty to let user input, OR populate one for demo.
    // Let's populate Long term with the user's example data for convenience?
    // User asked to "Let me input". I will leave it empty but the Edit modal has the logic.
  }, []);

  // Update Holdings from Input
  const handleUpdateHoldings = (type: PortfolioType, parsedData: any[]) => {
    // Generate simulated current price based on avg price (Since no real API)
    const newHoldings: Holding[] = parsedData.map(p => {
        // Simulate a random return between -10% and +20% for demo "current price"
        const randomReturn = (Math.random() * 0.3) - 0.1; 
        const simulatedPrice = p.avgPrice * (1 + randomReturn);

        return {
            id: generateId(),
            ticker: p.ticker,
            name: p.name,
            amount: p.amount,
            avgPrice: p.avgPrice,
            currentPrice: simulatedPrice, // SIMULATED
            change24h: (Math.random() * 4) - 2, // Random daily change
            market: currentMarket,
            portfolioType: type
        };
    });

    if (type === 'SHORT') setShortHoldings(newHoldings);
    if (type === 'MID') setMidHoldings(newHoldings);
    if (type === 'LONG') setLongHoldings(newHoldings);
  };

  const handleSelectHolding = (holding: Holding) => {
    setSelectedHolding(holding);
    const mockData = generateMockCandles(holding.currentPrice, 500);
    setChartData(mockData);
    setTimeout(() => {
        chartSectionRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  // --- Core Logic: Calculation & Overflow ---

  // 1. Calculate Raw Values (Before Overflow)
  const rawShortValue = useMemo(() => shortHoldings.reduce((sum, h) => sum + (h.amount * h.currentPrice), 0), [shortHoldings]);
  const rawMidValue = useMemo(() => midHoldings.reduce((sum, h) => sum + (h.amount * h.currentPrice), 0), [midHoldings]);
  const rawLongValue = useMemo(() => longHoldings.reduce((sum, h) => sum + (h.amount * h.currentPrice), 0), [longHoldings]);

  // 2. Calculate Overflow amounts
  const overflowShort = Math.max(0, rawShortValue - TARGET_SHORT);
  const overflowMid = Math.max(0, rawMidValue - TARGET_MID);

  // 3. Adjusted Values for Display in Original Columns (They cap at Target visually? Or show full? 
  // Requirement: "Show excess part in Family position".
  // Interpretation: The Short column shows up to 500k. The excess funds/holdings are visually attributed to Family.
  // Implementation: We won't split the holdings (too complex UI), we will just visualize the VALUE transfer.
  // The Short Column will display its Full Value, but indicate overflow. 
  // The Family Column will display the Overflow Value.

  const familyValue = overflowShort + overflowMid; // Family starts at 0 + overflows.

  // Total Net Worth (According to req: "1.2M excluding Family"). 
  // But wait, if Short overflows, is that overflow part of the 1.2M? 
  // Usually "Total Assets" = Sum of everything.
  // But the requirement says "Total position funds is 1.2M, excluding Family's 240k".
  // So the displayed "Net Worth" should probably be the sum of Short+Mid+Long (Actual).
  const totalAssets = rawShortValue + rawMidValue + rawLongValue;

  // Family Holdings: We don't actually move the specific stock records (unless we want to split shares).
  // For the Pie Chart in Family, we can create "Virtual Holdings" representing the overflow.
  const familyVirtualHoldings: Holding[] = [
      ...(overflowShort > 0 ? [{ id: 'ov-s', ticker: 'OVERFLOW', name: '來自短期溢出', amount: 1, avgPrice: 0, currentPrice: overflowShort, market: currentMarket, portfolioType: 'FAMILY', change24h: 0 } as Holding] : []),
      ...(overflowMid > 0 ? [{ id: 'ov-m', ticker: 'OVERFLOW', name: '來自中期溢出', amount: 1, avgPrice: 0, currentPrice: overflowMid, market: currentMarket, portfolioType: 'FAMILY', change24h: 0 } as Holding] : [])
  ];

  return (
    <div className="min-h-screen bg-dark-bg text-slate-200 pb-20 font-sans selection:bg-brand-primary selection:text-white">
      {/* Navbar */}
      <nav className="sticky top-0 z-50 bg-[#0b0e11]/80 backdrop-blur-md border-b border-dark-border">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-brand-primary to-brand-purple flex items-center justify-center shadow-lg shadow-brand-primary/20">
                    <LayoutDashboard size={18} className="text-white" />
                </div>
                <span className="font-bold text-xl tracking-tight text-white">Asset<span className="text-brand-secondary">Guard</span></span>
            </div>

            <div className="flex bg-[#161b22] rounded-full p-1 border border-dark-border">
              {(['TW', 'US', 'CRYPTO'] as MarketType[]).map((m) => (
                <button
                  key={m}
                  onClick={() => setCurrentMarket(m)}
                  className={`px-6 py-1.5 rounded-full text-sm font-medium transition-all duration-300 ${
                    currentMarket === m 
                    ? 'bg-dark-accent text-white shadow-sm border border-slate-600' 
                    : 'text-slate-500 hover:text-slate-300'
                  }`}
                >
                  {m === 'TW' ? '台股' : m === 'US' ? '美股' : '加密貨幣'}
                </button>
              ))}
            </div>

            <div className="flex items-center gap-4">
                 <button className="hidden md:flex items-center gap-2 px-4 py-2 rounded-lg bg-brand-primary hover:bg-indigo-600 text-white text-sm font-medium transition-colors shadow-lg shadow-indigo-500/20">
                    <Wallet size={16} />
                    <span>連結錢包</span>
                 </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

        {/* Top Summary Section */}
        <section className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {/* Total Value Card */}
            <div className="md:col-span-2 bg-gradient-to-r from-[#151a21] to-[#1a202c] p-8 rounded-2xl border border-dark-border relative overflow-hidden">
                <div className="absolute top-0 right-0 p-32 bg-brand-primary/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
                <div className="relative z-10">
                    <h2 className="text-slate-400 font-medium mb-2 flex items-center gap-2">
                        <Globe size={16} /> 總資產淨值 ({currentMarket})
                    </h2>
                    <div className="text-5xl font-bold text-white tracking-tight">
                        {formatCurrency(totalAssets)}
                    </div>
                    <div className="mt-4 flex items-center gap-3">
                         <div className="flex items-center gap-1 text-yellow-500 bg-yellow-500/10 px-2 py-1 rounded text-xs">
                            <Info size={12} />
                            <span>價格為模擬數據 (因無即時API)</span>
                         </div>
                    </div>
                </div>
            </div>

            {/* Market Status */}
            <div className="grid grid-rows-2 gap-4">
                 <div className="bg-dark-card border border-dark-border rounded-xl p-4 flex flex-col justify-center">
                     <div className="text-slate-500 text-xs mb-1">目標總本金 (不含家人)</div>
                     <div className="text-2xl font-bold text-white">{formatCurrency(TOTAL_PRINCIPAL)}</div>
                </div>
                 <div className="bg-dark-card border border-dark-border rounded-xl p-4 flex items-center justify-between">
                     <div>
                        <div className="text-slate-500 text-xs">股市狀態</div>
                        <div className="text-brand-success text-sm font-medium flex items-center gap-1">
                            <Activity size={14} /> 開盤中
                        </div>
                     </div>
                </div>
            </div>
        </section>

        {/* Portfolio Columns Section - 4 Columns now? No, User implied layout might need adjustment.
            "Short, Mid, Long" and "Family".
            Since layout is grid, we can do 4 columns or 2 rows. 
            Let's do 4 columns on large screens if possible, or wrap.
         */}
        <section className="grid grid-cols-1 lg:grid-cols-4 gap-4">
             {/* Short Term */}
             <PortfolioColumn 
                title="短期投資" 
                type="SHORT" 
                holdings={shortHoldings} 
                totalValue={rawShortValue}
                targetValue={TARGET_SHORT}
                currency="TWD"
                onSelectHolding={handleSelectHolding}
                onUpdateHoldings={handleUpdateHoldings}
                color="#06b6d4" // Cyan
             />

             {/* Mid Term */}
             <PortfolioColumn 
                title="中期投資" 
                type="MID" 
                holdings={midHoldings} 
                totalValue={rawMidValue}
                targetValue={TARGET_MID}
                currency="TWD"
                onSelectHolding={handleSelectHolding}
                onUpdateHoldings={handleUpdateHoldings}
                color="#8b5cf6" // Purple
             />

             {/* Long Term */}
             <PortfolioColumn 
                title="長期投資" 
                type="LONG" 
                holdings={longHoldings} 
                totalValue={rawLongValue}
                targetValue={TARGET_LONG}
                currency="TWD"
                onSelectHolding={handleSelectHolding}
                onUpdateHoldings={handleUpdateHoldings}
                color="#4f46e5" // Indigo
             />

             {/* Family (Overflow) */}
             <PortfolioColumn 
                title="家人備用金 (溢出區)" 
                type="FAMILY" 
                holdings={familyVirtualHoldings} 
                totalValue={familyValue}
                targetValue={TARGET_FAMILY}
                currency="TWD"
                onSelectHolding={() => {}} // Virtual holdings don't chart well
                color="#f59e0b" // Amber/Orange
                isOverflow={true}
                overflowSources={{ short: overflowShort, mid: overflowMid }}
             />
        </section>

        {/* Chart Section */}
        <section ref={chartSectionRef} className="pt-8">
            <div className="flex items-center justify-between mb-4">
                <h2 className="text-2xl font-bold text-white">技術分析 K線圖</h2>
                {selectedHolding && (
                    <span className="px-3 py-1 bg-dark-card border border-dark-border rounded-full text-sm text-slate-400">
                        正在查看: <span className="text-white font-medium">{selectedHolding.name} ({selectedHolding.ticker})</span>
                    </span>
                )}
            </div>

            {selectedHolding ? (
                <CandlestickChart data={chartData} ticker={selectedHolding.ticker} />
            ) : (
                <div className="w-full h-[400px] bg-dark-card rounded-xl border border-dark-border border-dashed flex flex-col items-center justify-center text-slate-500">
                    <Activity size={48} className="mb-4 opacity-50" />
                    <p className="text-lg">請點選上方任一持倉以查看K線走勢</p>
                    <p className="text-sm opacity-60">數據來源: 模擬生成 (因為無後端API連接)</p>
                </div>
            )}
        </section>

      </main>
    </div>
  );
};

