import React, { useState, useEffect, useMemo, useRef } from 'react';
import { MarketType, PortfolioType, Holding, CandleData } from './types';
import { generateMockCandles } from './services/mockData';
import PortfolioColumn from './components/PortfolioColumn';
import CandlestickChart from './components/CandlestickChart';
import { formatCurrency } from './utils/math';
import { Wallet, Globe, LayoutDashboard, Activity, Info, Edit3, Check, X, TrendingUp, TrendingDown } from 'lucide-react';
import { BarChart, Bar, XAxis, Tooltip as RechartsTooltip, ResponsiveContainer, Cell, ReferenceLine } from 'recharts';

const generateId = () => Math.random().toString(36).substr(2, 9);

// Generate last 7 trading days (skipping Sat/Sun)
const getRecentTradingDaysData = () => {
  const result = [];
  const mockValues = [-4500, 12000, 8500, -2300, 15600, 4200, 6800]; // Fixed mock values for demo
  const currentDate = new Date();
  let count = 0;

  // If today is weekend, start from Friday
  while (currentDate.getDay() === 0 || currentDate.getDay() === 6) {
     currentDate.setDate(currentDate.getDate() - 1);
  }

  // Generate 7 days backwards
  while (count < 7) {
    const dayOfWeek = currentDate.getDay();
    // 0 is Sunday, 6 is Saturday
    if (dayOfWeek !== 0 && dayOfWeek !== 6) {
       const month = currentDate.getMonth() + 1;
       const day = currentDate.getDate();
       const weekDays = ['日', '一', '二', '三', '四', '五', '六'];
       const label = `${month}/${day}(${weekDays[dayOfWeek]})`;

       // Add to beginning of array to maintain chronological order (Oldest -> Newest)
       result.unshift({
           day: label,
           value: mockValues[6 - count] // Map to mock values in reverse
       });
       count++;
    }
    // Move to previous day
    currentDate.setDate(currentDate.getDate() - 1);
  }
  return result;
};

const MOCK_PNL_DATA = getRecentTradingDaysData();

const App: React.FC = () => {
  const [currentMarket, setCurrentMarket] = useState<MarketType>('TW');

  // Principal State (Editable)
  const [principal, setPrincipal] = useState<number>(1200000);
  const [isEditingPrincipal, setIsEditingPrincipal] = useState(false);
  const [tempPrincipal, setTempPrincipal] = useState<string>('1200000');

  // State for different buckets
  const [shortHoldings, setShortHoldings] = useState<Holding[]>([]);
  const [midHoldings, setMidHoldings] = useState<Holding[]>([]);
  const [longHoldings, setLongHoldings] = useState<Holding[]>([]);

