  const TARGET_SHORT = 500000; // Fixed
  const TARGET_FAMILY = 240000; // Fixed (Not part of principal logic, purely separate bucket size)

  // Dynamic Targets based on Principal
  const targetLong = Math.floor(principal * 0.30);
  const targetMid = Math.max(0, principal - TARGET_SHORT - targetLong);

  // Initial Setup
  useEffect(() => {
    // Initial load logic if needed
  }, []);

  // Update Holdings from Input
  const handleUpdateHoldings = (type: PortfolioType, parsedData: any[]) => {
    const newHoldings: Holding[] = parsedData.map(p => {
        // Simulate a random return between -10% and +20% for demo
        const randomReturn = (Math.random() * 0.3) - 0.1; 
        const simulatedPrice = p.avgPrice * (1 + randomReturn);

        return {
            id: generateId(),
            ticker: p.ticker,
            name: p.name,
            amount: p.amount,
            avgPrice: p.avgPrice,
            currentPrice: simulatedPrice,
            change24h: (Math.random() * 4) - 2,
            market: currentMarket,
            portfolioType: type
        };
    });

    if (type === 'SHORT') setShortHoldings(newHoldings);
    if (type === 'MID') setMidHoldings(newHoldings);
    if (type === 'LONG') setLongHoldings(newHoldings);
  };

  const handleSelectHolding = (holding: Holding) => {
    setSelectedHolding(holding);
    const mockData = generateMockCandles(holding.currentPrice, 500);
    setChartData(mockData);
    setTimeout(() => {
        chartSectionRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  const handleSavePrincipal = () => {
      const val = parseInt(tempPrincipal.replace(/,/g, ''), 10);
      if (!isNaN(val)) {
