          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-brand-primary to-brand-purple flex items-center justify-center shadow-lg shadow-brand-primary/20">
                    <LayoutDashboard size={18} className="text-white" />
                </div>
                <span className="font-bold text-xl tracking-tight text-white">Asset<span className="text-brand-secondary">Guard</span></span>
            </div>

            <div className="flex bg-[#161b22] rounded-full p-1 border border-dark-border">
              {(['TW', 'US', 'CRYPTO'] as MarketType[]).map((m) => (
                <button
                  key={m}
                  onClick={() => setCurrentMarket(m)}
                  className={`px-6 py-1.5 rounded-full text-sm font-medium transition-all duration-300 ${
                    currentMarket === m 
                    ? 'bg-dark-accent text-white shadow-sm border border-slate-600' 
                    : 'text-slate-500 hover:text-slate-300'
                  }`}
                >
                  {m === 'TW' ? '台股' : m === 'US' ? '美股' : '加密貨幣'}
                </button>
              ))}
            </div>

            <div className="flex items-center gap-4">
                 <button className="hidden md:flex items-center gap-2 px-4 py-2 rounded-lg bg-brand-primary hover:bg-indigo-600 text-white text-sm font-medium transition-colors shadow-lg shadow-indigo-500/20">
                    <Wallet size={16} />
                    <span>連結錢包</span>
                 </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

        {/* Top Summary Section */}
        <section className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* 1. Total Holdings (Left) */}
            <div className="lg:col-span-4 bg-gradient-to-br from-[#151a21] to-[#1a202c] p-6 rounded-2xl border border-dark-border relative overflow-hidden flex flex-col justify-between">
                <div className="absolute top-0 right-0 p-24 bg-brand-primary/5 rounded-full blur-3xl -mr-12 -mt-12 pointer-events-none"></div>
                <div>
                    <h2 className="text-slate-400 font-medium mb-2 flex items-center gap-2">
                        <Globe size={16} /> 目前持倉 ({currentMarket})
                    </h2>
                    <div className="text-4xl xl:text-5xl font-bold text-white tracking-tight mt-2">
                        {formatCurrency(totalAssets)}
                    </div>
                </div>
                <div className="mt-6 flex items-center gap-3">
                     <div className="flex items-center gap-1 text-yellow-500 bg-yellow-500/10 px-2 py-1 rounded text-xs">
                        <Info size={12} />
                        <span>四倉位總市值</span>
                     </div>
                </div>
            </div>

            {/* 2. P&L Chart (Middle - New) */}
            <div className="lg:col-span-5 bg-dark-card border border-dark-border rounded-2xl p-5 flex flex-col">
                <div className="flex justify-between items-center mb-4">
                     <h3 className="text-slate-300 text-sm font-medium flex items-center gap-2">
                        <Activity size={14} className="text-brand-secondary"/> 近7日未實現損益變化
                     </h3>
