                </div>
                <div className="flex-1 w-full h-[140px]">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={MOCK_PNL_DATA} margin={{ top: 5, right: 5, left: -20, bottom: 0 }}>
                            <XAxis dataKey="day" hide />
