                </div>
            </div>

            {/* 3. Funds & Status (Right) */}
            <div className="lg:col-span-3 flex flex-col gap-4">
                 {/* Editable Funds */}
                 <div className="bg-dark-card border border-dark-border rounded-xl p-5 flex-1 flex flex-col justify-center relative group">
                     <div className="flex justify-between items-center mb-1">
                        <div className="text-slate-500 text-xs">資金 (不含家人)</div>
                        {!isEditingPrincipal && (
                            <button 
                                onClick={() => {
                                    setTempPrincipal(principal.toString());
                                    setIsEditingPrincipal(true);
                                }}
                                className="text-slate-600 hover:text-brand-primary transition-colors p-1"
                            >
                                <Edit3 size={14} />
                            </button>
                        )}
                     </div>

                     {isEditingPrincipal ? (
                         <div className="flex items-center gap-2 animate-in fade-in duration-200">
                            <input 
